class Solution {
    fun largestComponentSize(nums:IntArray):Int{
        val parent=IntArray(nums.size){
            it
        };
        val size=IntArray(nums.size){
            1
        };
        fun find(xInput:Int):Int{
            var x=xInput;
            while(parent[x]!=x){
                parent[x]=parent[parent[x]];
                x=parent[x]
            };
            return x
        };
        fun union(aInput:Int,bInput:Int){
            var a=find(aInput);
            var b=find(bInput);
            if(a==b)return;
            if(size[a]<size[b]){
                val t=a;
                a=b;
                b=t
            };
            parent[b]=a;
            size[a]+=size[b]
        };
        val owner=mutableMapOf<Int,Int>();
        fun connect(factor:Int,index:Int){
            val other=owner.putIfAbsent(factor,index);
            if(other!=null)union(index,other)
        };
        for(i in nums.indices){
            var value=nums[i];
            var factor=2;
            while(factor*factor<=value){
                if(value%factor==0){
                    connect(factor,i);
                    while(value%factor==0)value/=factor
                };
                factor++
            };
            if(value>1)connect(value,i)
        };
        return nums.indices.filter{
            find(it)==it
        }.maxOf{
            size[it]
        }
    }
}

